function renderStats(){const done=state.tasks.filter(t=>t.completed).length;$('statDone').textContent=done;$('statDoneFoot').textContent=done?`${done} quest${done===1?'':'s'} completed`: 'Your first win is waiting';$('streakValue').textContent=currentStreak();$('statFocus').textContent=state.focusMinutes||0;$('dateToday').textContent=new Intl.DateTimeFormat(undefined,{weekday:'short',month:'short',day:'numeric'}).format(new Date());$('todayLabel').textContent=new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(new Date());}
function renderTasks(){const list=$('questList');list.replaceChildren();const search=$('searchInput').value.trim().toLowerCase();let tasks=state.tasks.filter(t=>{if(filter==='active'&&t.completed)return false;if(filter==='completed'&&!t.completed)return false;if(filter==='today'&&t.due!==dayKey()&&!(!t.due&& !t.completed))return false;if(search&&!`${t.text} ${CATEGORIES[t.category]||t.category}`.toLowerCase().includes(search))return false;return true});const sort=$('sortSelect').value;if(sort==='due')tasks.sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));if(sort==='priority')tasks.sort((a,b)=>(XP[b.priority]||0)-(XP[a.priority]||0));if(sort==='created')tasks.sort((a,b)=>(b.created||0)-(a.created||0));for(const task of tasks)list.append(buildTask(task));$('emptyState').classList.toggle('show',tasks.length===0);$('questCount').textContent=state.tasks.filter(t=>!t.completed).length;$('countAll').textContent=state.tasks.length;$('countActive').textContent=state.tasks.filter(t=>!t.completed).length;$('countCompleted').textContent=state.tasks.filter(t=>t.completed).length;$('countToday').textContent=state.tasks.filter(t=>t.due===dayKey()&&!t.completed).length}
function buildTask(t){const li=document.createElement('article');li.className=`quest-item ${t.completed?'completed':''}`;if(t.completed&&Date.now()-(t.completedAt||0)<1100)li.classList.add('just-completed');li.draggable=true;li.dataset.id=t.id;li.addEventListener('dragstart',()=>{dragId=t.id;li.classList.add('dragging')});li.addEventListener('dragend',()=>li.classList.remove('dragging'));const check=document.createElement('input');check.type='checkbox';check.className='quest-check';check.checked=!!t.completed;check.setAttribute('aria-label',`${t.completed?'Reopen':'Complete'} ${t.text}`);check.addEventListener('change',()=>toggleTask(t.id));const main=document.createElement('div');main.className='quest-main';if(activeEdit===t.id){const input=document.createElement('input');input.className='quest-input';input.value=t.text;input.maxLength=140;input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();saveEdit(t.id,input.value)}if(e.key==='Escape'){activeEdit=null;renderTasks()}});input.addEventListener('blur',()=>saveEdit(t.id,input.value));main.append(input);setTimeout(()=>{input.focus();input.select()},0)}else{const title=document.createElement('div');title.className='quest-title';title.textContent=t.text;main.append(title);if(t.demoSample){const demo=document.createElement('span');demo.className='demo-tag';demo.textContent='DEMO';title.append(demo)}}const meta=document.createElement('div');meta.className='quest-meta';meta.innerHTML=`<span class="tag category">${escapeHtml(CATEGORIES[t.category]||'Other')}</span><span class="tag priority-${escapeHtml(t.priority)}">${t.priority==='high'?'Hard':t.priority==='medium'?'Medium':'Easy'} · +${XP[t.priority]||10} XP</span>${t.est?`<span class="tag">◷ ${Number(t.est)} min</span>`:''}${t.due?`<span class="tag ${dayOffset(t.due)<0&&!t.completed?'due-overdue':dayOffset(t.due)<=2&&!t.completed?'due-soon':''}">◷ ${escapeHtml(dueDescription(t.due))}</span>`:''}${t.repeat&&t.repeat!=='none'?`<span class="tag">↻ ${escapeHtml(t.repeat)}</span>`:''}`;main.append(meta);const actions=document.createElement('div');actions.className='quest-actions';actions.innerHTML=`<button class="mini-action" title="${timerRunning?'Focus on this quest':'Link to focus timer'}" data-action="focus"><i class="fa-solid fa-bullseye"></i></button><button class="mini-action" title="Add subtask" data-action="subtask"><i class="fa-solid fa-list-ul"></i></button><button class="mini-action" title="Edit quest" data-action="edit"><i class="fa-solid fa-pen"></i></button><button class="mini-action" title="Delete quest" data-action="delete"><i class="fa-solid fa-trash"></i></button>`;actions.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action==='focus'){$('focusTask').value=t.id;document.querySelector('#focus').scrollIntoView({behavior:'smooth',block:'center'});toast('Quest linked to your focus session.')}if(action==='edit'){activeEdit=t.id;renderTasks()}if(action==='delete')deleteTask(t.id);if(action==='subtask')addSubtaskPrompt(t.id)});li.append(check,main,actions);if(t.subtasks?.length){const subs=document.createElement('div');subs.className='subtasks';for(const sub of t.subtasks){const row=document.createElement('label');row.className=`subtask ${sub.done?'done':''}`;const cb=document.createElement('input');cb.type='checkbox';cb.checked=!!sub.done;cb.addEventListener('change',()=>toggleSubtask(t.id,sub.id));const text=document.createElement('span');text.textContent=sub.text;row.append(cb,text);subs.append(row)}main.append(subs)}li.addEventListener('dragover',e=>e.preventDefault());li.addEventListener('drop',e=>{e.preventDefault();if(dragId&&dragId!==t.id)reorderTasks(dragId,t.id)});return li}
function saveEdit(id,text){const clean=text.trim();if(!clean){activeEdit=null;renderTasks();return}const task=state.tasks.find(t=>t.id===id);if(task&&task.text!==clean){task.text=clean;persist()}activeEdit=null;renderTasks()}
function reorderTasks(from,to){const a=state.tasks.findIndex(t=>t.id===from),b=state.tasks.findIndex(t=>t.id===to);if(a<0||b<0)return;const [item]=state.tasks.splice(a,1);state.tasks.splice(b,0,item);persist();renderTasks()}
function createTask(data){const text=data.text.trim();if(!text)return;state.tasks.unshift({id:crypto.randomUUID?.()||String(Date.now()),text,category:data.category,priority:data.priority,est:data.est||null,due:data.due||null,repeat:data.repeat||'none',completed:false,subtasks:[],created:Date.now(),completedAt:null});persist();render();playSfx('add');toast('Quest added. Your next win is on the board.');}
function repeatInterval(repeat,date){const d=new Date(`${date||dayKey()}T12:00:00`);if(repeat==='daily')d.setDate(d.getDate()+1);else if(repeat==='3days')d.setDate(d.getDate()+3);else if(repeat==='weekly')d.setDate(d.getDate()+7);else if(repeat==='2weeks')d.setDate(d.getDate()+14);else if(repeat==='monthly')d.setMonth(d.getMonth()+1);else return null;return dayKey(d)}
function strikeBoss(amount){const before=state.bossHp;state.bossHp=Math.max(0,state.bossHp-amount);$('bossArt').classList.remove('hit');void $('bossArt').offsetWidth;$('bossArt').classList.add('hit');playSfx('boss');floatBossDamage(amount);if(before>0&&state.bossHp===0)toast('Boss defeated! The week is yours.');else toast(`Dragon struck for ${amount} damage!`)}
function toggleTask(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;const levelBefore=levelInfo().rank.level;t.completed=!t.completed;if(t.completed){const snapshot={xp:state.xp,gold:state.gold||0,energy:state.petEnergy,bossHp:state.bossHp,activity:state.activity[dayKey()]||0,subtasks:(t.subtasks||[]).map(s=>({...s})),task:t,taskIndex:state.tasks.indexOf(t),cloneId:null};t.completedAt=Date.now();const gain=XP[t.priority]||10,goldGain=t.priority==='high'?5:t.priority==='medium'?4:3,energyBefore=state.petEnergy,bossBefore=state.bossHp;state.xp+=gain;state.gold=(state.gold||0)+goldGain;floatReward('+'+gain+' XP · +'+goldGain+' gold');state.petEnergy=Math.min(100,state.petEnergy+8);state.activity[dayKey()]=(state.activity[dayKey()]||0)+1;strikeBoss(gain);if(t.demoSample)t.demoReward={xp:gain,gold:goldGain,energy:state.petEnergy-energyBefore,bossDamage:bossBefore-state.bossHp,day:dayKey(),week:state.bossWeek};t.subtasks=(t.subtasks||[]).map(s=>({...s,done:true}));const next=repeatInterval(t.repeat,t.due||dayKey());if(next){const clone={...t,id:crypto.randomUUID?.()||String(Date.now()+1),due:next,completed:false,completedAt:null,created:Date.now(),subtasks:(t.subtasks||[]).map(s=>({...s,id:crypto.randomUUID?.()||String(Math.random()),done:false})),demoReward:null};snapshot.cloneId=clone.id;state.tasks.unshift(clone)}playTone(true);animatePet();if(state.activity[dayKey()]>=3&&!state.bounties[dayKey()]?.claimed)toast('Daily bounty complete. Claim your 30 XP reward!');persist();render();celebrateLevel(levelBefore);toast('Quest completed.','success',{label:'Undo',run:()=>{state.xp=snapshot.xp;state.gold=snapshot.gold;state.petEnergy=snapshot.energy;state.bossHp=snapshot.bossHp;state.activity[dayKey()]=snapshot.activity;t.completed=false;t.completedAt=null;t.demoReward=null;t.subtasks=snapshot.subtasks;if(snapshot.cloneId)state.tasks=state.tasks.filter(x=>String(x.id)!==String(snapshot.cloneId));persist();render()}});return}t.completedAt=null;state.xp=Math.max(0,state.xp-(XP[t.priority]||10));state.gold=Math.max(0,(state.gold||0)-(t.priority==='high'?5:t.priority==='medium'?4:3));state.activity[dayKey()]=Math.max(0,(state.activity[dayKey()]||0)-1);if(t.demoSample&&t.demoReward){state.petEnergy=Math.max(0,state.petEnergy-t.demoReward.energy);if(t.demoReward.week===state.bossWeek)state.bossHp=Math.min(500,state.bossHp+t.demoReward.bossDamage);t.demoReward=null}persist();render()}function deleteTask(id){const index=state.tasks.findIndex(x=>x.id===id);if(index<0)return;const [task]=state.tasks.splice(index,1);persist();render();toast('Quest deleted.','success',{label:'Undo',run:()=>{state.tasks.splice(Math.min(index,state.tasks.length),0,task);persist();render()}})}
function addSubtaskPrompt(id){const text=prompt('What is one small step?');if(!text?.trim())return;const t=state.tasks.find(x=>x.id===id);if(!t)return;t.subtasks=t.subtasks||[];t.subtasks.push({id:crypto.randomUUID?.()||String(Date.now()),text:text.trim(),done:false});persist();renderTasks()}
function toggleSubtask(taskId,subId){const t=state.tasks.find(x=>x.id===taskId),s=t?.subtasks?.find(x=>x.id===subId);if(!s)return;s.done=!s.done;if(s.done){state.xp+=5;state.petEnergy=Math.min(100,state.petEnergy+2);playTone(false)}else state.xp=Math.max(0,state.xp-5);persist();render()}
function renderCompanion(){const lvl=levelInfo().rank.level;const pet=lvl>=4?'🧙‍♂️':lvl>=2?'🐉':'🥚';const name=lvl>=4?'Sage companion':lvl>=2?'Little dragon':'Hatchling egg';$('petAvatar').textContent=pet;$('sidebarPet').textContent=pet;$('petName').textContent=name;$('sidebarPetName').textContent=name;const low=state.petEnergy<=20;$('petAvatar').classList.toggle('sleeping',low);$('petMood').textContent=low?'Your companion needs a little care':state.petEnergy>75?'Feeling bright and bouncy':'Growing alongside you';$('sidebarPetMood').textContent=low?'A little sleepy':'Ready to grow';$('petEnergy').textContent=state.petEnergy;$('energyFill').style.width=`${state.petEnergy}%`;$('feedPet').disabled=state.petEnergy>=100||state.xp<10}
