function mondayOf(date){const d=new Date(date);d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return d}
function renderWeekly(){const monday=mondayOf(new Date()),days=Array.from({length:7},(_,i)=>shiftDate(monday,i));const keys=days.map(dayKey),quests=keys.reduce((n,k)=>n+(state.activity[k]||0),0),focus=keys.reduce((n,k)=>n+(state.focusByDay[k]||0),0);$('weekQuestCount').textContent=quests;$('weekFocusCount').innerHTML=`${focus}<span>m</span>`;$('weekQuestGoal').textContent=`${Math.min(quests,15)} / 15`;$('weekQuestProgress').style.width=`${Math.min(100,quests/15*100)}%`;$('weekRange').textContent=`${new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(days[0])} – ${new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(days[6])}`;const wrap=$('weekDays');wrap.replaceChildren();days.forEach((d,i)=>{const key=keys[i],count=state.activity[key]||0,bar=document.createElement('span');bar.className=`week-day ${count?'active':''} ${key===dayKey()?'today':''}`;bar.style.height=`${Math.min(27,6+count*5)}px`;bar.title=`${new Intl.DateTimeFormat(undefined,{weekday:'long'}).format(d)} · ${count} quests`;wrap.append(bar)})}
function renderUpcoming(){const wrap=$('upcomingList');wrap.replaceChildren();const pending=state.tasks.filter(t=>!t.completed);const due=pending.filter(t=>t.due).sort((a,b)=>a.due.localeCompare(b.due));const items=(due.length?due:pending).slice(0,3);if(!items.length){const empty=document.createElement('div');empty.className='upcoming-empty';empty.textContent='You’re all caught up. Add a quest and it will show up here.';wrap.append(empty);return}items.forEach(t=>{const row=document.createElement('div');row.className='upcoming-item';const date=document.createElement('span');date.className=`upcoming-date ${t.due===dayKey()?'today':''}`;if(t.due){const d=new Date(`${t.due}T12:00:00`);date.textContent=t.due===dayKey()?'TODAY':new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(d)}else date.innerHTML='<i class="fa-solid fa-list-check"></i>';const body=document.createElement('div'),title=document.createElement('div'),meta=document.createElement('div'),dot=document.createElement('span');title.className='upcoming-title';title.textContent=t.text;meta.className='upcoming-meta';meta.textContent=t.due?`${CATEGORIES[t.category]||'Quest'} · ${t.due<dayKey()?'Overdue':'Due date'}`:`${CATEGORIES[t.category]||'Quest'} · No due date`;dot.className=`upcoming-priority ${t.priority||'low'}`;body.append(title,meta);row.append(date,body,dot);row.title='Open this quest on the board';row.addEventListener('click',()=>{const input=$('searchInput');input.value=t.text;filter='all';document.querySelectorAll('.board-tab').forEach(b=>{const selected=b.dataset.filter==='all';b.classList.toggle('active',selected);b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1});renderTasks();$('quests').scrollIntoView({behavior:'smooth',block:'start'})});wrap.append(row)})}
function renderHeatmap(){const days=analyticsRange==='month'?30:365;const container=$('heatmap');container.replaceChildren();const start=shiftDate(new Date(),-(days-1));start.setDate(start.getDate()-((start.getDay()+6)%7));const actualStart=analyticsRange==='month'?shiftDate(new Date(),-29):shiftDate(new Date(),-364);const months=[];for(let i=0;i<days;i++){const date=shiftDate(actualStart,i),key=dayKey(date),n=state.activity[key]||0;const c=document.createElement('span');c.className='heat-cell';const intensity=n===0?0:n===1?1:n<=3?2:n<=5?3:4;c.classList.add(`heat-${intensity}`);c.title=`${key}: ${n} completed`;container.append(c);if(date.getDate()===1||i===0)months.push({index:i,label:new Intl.DateTimeFormat(undefined,{month:'short'}).format(date)})}const monthsEl=$('heatmapMonths');monthsEl.replaceChildren();for(const m of months){const span=document.createElement('span');span.textContent=m.label;monthsEl.append(span)}const total=Object.entries(state.activity).filter(([d])=>d>=dayKey(shiftDate(new Date(),-days+1))).reduce((sum,[,n])=>sum+n,0);$('activitySummary').textContent=`${total} quests completed in the last ${analyticsRange==='month'?'30 days':'year'}`}
function renderFocusTasks(){const select=$('focusTask'),current=select.value||restoredFocusTaskId;select.replaceChildren(new Option('Choose a quest (optional)',''));for(const t of state.tasks.filter(t=>!t.completed))select.add(new Option(t.text,t.id));if(state.tasks.some(t=>String(t.id)===current&&!t.completed))select.value=current;restoredFocusTaskId=''}
function renderTheme(){document.body.classList.remove('theme-cyberpunk','theme-amoled','theme-sunset');if(state.theme!=='default')document.body.classList.add(`theme-${state.theme}`)}
function completeFocus(){if(completionInProgress)return;completionInProgress=true;const completionKey=focusSessionId?'tasksphere.focus-completed.'+focusSessionId:'';if(completionKey&&localStorage.getItem(completionKey)){clearInterval(timerInterval);timerRunning=false;saveTimerSession('done');updateTimerUI();completionInProgress=false;return}if(completionKey){localStorage.setItem(completionKey,String(Date.now()));setTimeout(()=>localStorage.removeItem(completionKey),30*86400000)}timerRunning=false;clearInterval(timerInterval);timerInterval=null;timerDeadline=0;saveTimerSession('done');$('timerStart').innerHTML='<i class="fa-solid fa-play"></i> Start focus';$('focusStatus').textContent='COMPLETE';state.focusMinutes=(state.focusMinutes||0)+(state.focus.mode==='focus'?(state.focus.minutes||25):0);if(state.focus.mode==='focus'){const previous=levelInfo().rank.level;state.xp+=50;state.petEnergy=Math.min(100,state.petEnergy+5);state.activity[dayKey()]=(state.activity[dayKey()]||0)+1;state.focusByDay=state.focusByDay||{};state.focusByDay[dayKey()]=(state.focusByDay[dayKey()]||0)+(state.focus.minutes||25);const linked=state.tasks.find(t=>String(t.id)===$('focusTask').value);if(linked)linked.focusMinutes=(linked.focusMinutes||0)+(state.focus.minutes||25);$('timerMode').textContent='BREAK';focusSeconds=5*60;state.focus={minutes:5,mode:'break'};playSfx('bounty');floatReward('+50 XP');celebrateLevel(previous);toast('Focus session complete · +50 XP. Take a short break.')}else{state.focus={minutes:state.focusDefault||25,mode:'focus'};focusSeconds=(state.focusDefault||25)*60;playSfx('success');toast('Break complete. Ready for another round?')}$('timerDisplay').textContent=formatTime(focusSeconds);persist();render();updateTimerUI();completionInProgress=false;focusSessionId=''}
function formatTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function updateTimerUI(){const mins=state.focus.minutes||25;$('timerDisplay').textContent=formatTime(focusSeconds);$('timerMode').textContent=state.focus.mode==='break'?'BREAK':'FOCUS';$('timerCaption').textContent=timerRunning?(state.focus.mode==='break'?'Rest your eyes and breathe':'Stay with this moment'):state.focus.mode==='break'?'Take a moment to recharge':'Ready when you are';$('timerRing').classList.toggle('timer-active',timerRunning);$('focusStatus').textContent=timerRunning?'IN SESSION':state.focus.mode==='break'?'BREAK':'READY';$('focus').classList.toggle('is-running',timerRunning&&state.focus.mode==='focus');const progress=focusSeconds/(mins*60);$('timerRing').style.setProperty('--timer-progress',`${(1-progress)*100}%`);document.title=timerRunning?`${formatTime(focusSeconds)} · TaskSphere Focus`:'TaskSphere — Make progress feel good'}
function tickTimer(){if(!timerRunning)return;const remaining=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));focusSeconds=remaining;const minuteMark=Math.ceil(remaining/60);if(state.minuteChime&&state.focus.mode==='focus'&&remaining>0&&lastChimeMinute!==null&&minuteMark<lastChimeMinute){lastChimeMinute=minuteMark;playSfx('minute')}updateTimerUI();if(remaining===0)completeFocus()}
function startTimer(){if(timerRunning){focusSeconds=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));clearInterval(timerInterval);timerRunning=false;timerDeadline=0;saveTimerSession('paused');$('timerStart').innerHTML='<i class="fa-solid fa-play"></i> Resume focus';updateTimerUI();return}timerRunning=true;if(!focusSessionId)focusSessionId=crypto.randomUUID?.()||String(Date.now());timerDeadline=Date.now()+focusSeconds*1000;lastChimeMinute=Math.ceil(focusSeconds/60);saveTimerSession('running');$('timerStart').innerHTML='<i class="fa-solid fa-pause"></i> Pause session';playSfx('tap');updateTimerUI();timerInterval=setInterval(tickTimer,250)}
function setTimerMinutes(n){if(timerRunning||state.focus.mode==='break')return;state.focus={minutes:n,mode:'focus'};focusSeconds=n*60;document.querySelectorAll('.timer-presets button').forEach(b=>b.classList.toggle('selected',Number(b.dataset.minutes)===n));persist();if(!timerRunning)saveTimerSession('paused');updateTimerUI()}
function toggleChime(){state.minuteChime=!state.minuteChime;const b=$('chimeToggle');b.setAttribute('aria-pressed',String(state.minuteChime));b.querySelector('.option-state').textContent=state.minuteChime?'On':'Off';persist();if(state.minuteChime){lastChimeMinute=Math.ceil(focusSeconds/60);playSfx('minute')}}
function renderFocusControls(){const b=$('chimeToggle');if(!b)return;b.setAttribute('aria-pressed',String(!!state.minuteChime));b.querySelector('.option-state').textContent=state.minuteChime?'On':'Off'}
function toggleImmersive(){const active=document.body.classList.toggle('focus-immersive');$('immersiveToggle').setAttribute('aria-pressed',String(active));$('immersiveToggle').innerHTML=`<i class="fa-solid ${active?'fa-compress':'fa-expand'}"></i><span>${active?'Exit focus mode':'Focus mode'}</span>`;if(active)$('timerStart').focus()}
let audioContext=null;
function playSfx(kind='success'){
  if(state.soundEnabled===false)return;
  try{
    const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return;
    audioContext=audioContext||new Ctx();if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});
    const patterns={
      success:[[660,0,.11,'sine',.05],[880,.08,.17,'sine',.045]],
      minute:[[660,0,.065,'sine',.014],[880,.065,.09,'sine',.012]],
      add:[[520,0,.07,'triangle',.035],[760,.06,.11,'sine',.04]],
      tap:[[920,0,.055,'triangle',.025]],
      error:[[260,0,.14,'triangle',.055],[185,.1,.2,'triangle',.05]],
      boss:[[145,0,.13,'sawtooth',.045],[95,.1,.18,'triangle',.05]],
      level:[[523,0,.12,'sine',.04],[659,.09,.12,'sine',.04],[784,.18,.12,'sine',.045],[1047,.27,.25,'sine',.05]],
      bounty:[[659,0,.1,'triangle',.04],[784,.08,.1,'sine',.045],[988,.16,.1,'sine',.045],[1318,.24,.28,'sine',.05]]
    };
    for(const [frequency,offset,duration,wave,volume] of (patterns[kind]||patterns.success)){
      const oscillator=audioContext.createOscillator(),gain=audioContext.createGain(),start=audioContext.currentTime+offset;
      oscillator.type=wave;oscillator.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);
      gain.gain.exponentialRampToValueAtTime(Math.max(.0001,volume*(state.soundVolume??.45)/.45),start+.012);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);
      oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start(start);oscillator.stop(start+duration+.02);
    }
  }catch{}
}
function playTone(success){playSfx(success?'success':'tap')}
function toggleSound(){state.soundEnabled=state.soundEnabled===false;renderSoundControl();persist();if(state.soundEnabled)playSfx('success');else toast('Sounds muted.')}
function renderSoundControl(){const button=$('soundToggle');if(!button)return;const enabled=state.soundEnabled!==false;button.setAttribute('aria-pressed',String(enabled));button.setAttribute('aria-label',enabled?'Turn sound off':'Turn sound on');button.title=enabled?'Sound on':'Sound off';button.innerHTML=`<i class="fa-solid ${enabled?'fa-volume-high':'fa-volume-xmark'}"></i>`}
function floatReward(message,target=$('statXp')){if(!target)return;const box=target.getBoundingClientRect(),node=document.createElement('span');node.className='reward-float';node.textContent=message;node.style.left=`${box.left+box.width/2}px`;node.style.top=`${box.top-4}px`;document.body.append(node);setTimeout(()=>node.remove(),1150)}
function floatBossDamage(amount){const target=$('bossArt'),box=target.getBoundingClientRect(),node=document.createElement('span');node.className='boss-damage';node.textContent=`−${amount}`;node.style.left=`${box.left+box.width/2}px`;node.style.top=`${box.top+box.height/3}px`;document.body.append(node);setTimeout(()=>node.remove(),900)}
function celebrateLevel(previous){const current=levelInfo().rank;if(current.level<=previous)return;playSfx('level');$('rankEmblem').classList.remove('level-up');void $('rankEmblem').offsetWidth;$('rankEmblem').classList.add('level-up');toast(`Level up! You reached Level ${current.level}: ${current.name}.`)}
function animatePet(){const p=$('petAvatar');p.classList.remove('happy');void p.offsetWidth;p.classList.add('happy');setTimeout(()=>p.classList.remove('happy'),1300)}
function feedPet(){if(state.petEnergy>=100)return toast('Your companion is already full.');if(state.xp<10)return toast('Earn 10 XP to feed your companion.','error');state.xp-=10;state.petEnergy=Math.min(100,state.petEnergy+20);animatePet();persist();render();toast('Your companion is feeling better.')}
