function claimBounty(){if(completedToday()<3||bountyClaimed())return;const levelBefore=levelInfo().rank.level;state.xp+=30;state.gold=(state.gold||0)+15;state.bounties[dayKey()]={claimed:true};persist();render();playSfx('bounty');floatReward('+30 XP · +15 gold');celebrateLevel(levelBefore);toast('Daily bounty claimed · +30 XP and 15 gold!')}
function applyTheme(id){const theme=THEMES.find(t=>t.id===id);if(!theme||levelInfo().rank.level<theme.level)return toast(`Reach Level ${theme.level} to unlock ${theme.name}.`,'error');state.unlockedThemes=state.unlockedThemes||['default'];if(!state.unlockedThemes.includes(id)){if((state.gold||0)<theme.cost)return toast(`You need ${theme.cost} gold to unlock ${theme.name}.`,'error');state.gold-=theme.cost;state.unlockedThemes.push(id);toast(`${theme.name} unlocked for ${theme.cost} gold.`)}state.theme=id;persist();renderTheme();render();showShop();}
function applyMotionPreference(){document.body.classList.remove('motion-subtle','motion-reduced');if(state.motionLevel==='subtle')document.body.classList.add('motion-subtle');if(state.motionLevel==='reduced')document.body.classList.add('motion-reduced')}
function openQuickAdd(){const box=document.createElement('form');box.className='quick-add-form';box.innerHTML='<div class="section-kicker">CAPTURE IT BEFORE YOU FORGET</div><h2 id="modalTitle">Quick add a quest</h2><label for="quickQuestInput">What do you need to do?</label><input class="quest-input" id="quickQuestInput" maxlength="140" placeholder="Write a clear next step…" required><div class="modal-field"><label for="quickQuestCategory">Category</label><select id="quickQuestCategory"><option value="study">Study</option><option value="work">Work</option><option value="wellness">Wellness</option><option value="life">Life admin</option></select></div><button class="primary-btn full" type="submit"><i class="fa-solid fa-plus"></i> Add quest</button><p class="setup-note">Shortcut: press N from anywhere · Ctrl/Cmd + K also opens actions.</p>';openModal(box);box.addEventListener('submit',e=>{e.preventDefault();createTask({text:$('quickQuestInput').value,category:$('quickQuestCategory').value,priority:'medium',repeat:'none'});openModalClose()});$('quickQuestInput').focus()}
function loadDemoQuests(){const samples=[['Plan the week’s top three priorities','work','high',dayKey(),false],['Take a 10 minute walk','wellness','low',dayKey(),false],['Review notes from yesterday','study','medium',dayKey(shiftDate(new Date(),1)),false],['Review weekly goals','work','medium',dayKey(),true]];let count=0;for(const [text,category,priority,due,completed] of samples){if(state.tasks.some(t=>t.demoSample&&t.text===text))continue;const task={id:crypto.randomUUID?.()||String(Date.now()+count++),text,category,priority,due,repeat:'none',completed,subtasks:[],created:Date.now(),completedAt:completed?Date.now():null,demoSample:true,demoReward:null};if(completed){const energyBefore=state.petEnergy,bossBefore=state.bossHp,gain=XP[priority],goldGain=priority==='high'?5:priority==='medium'?4:3;state.xp+=gain;state.gold=(state.gold||0)+goldGain;state.petEnergy=Math.min(100,state.petEnergy+8);state.activity[dayKey()]=(state.activity[dayKey()]||0)+1;state.bossHp=Math.max(0,state.bossHp-gain);task.demoReward={xp:gain,gold:goldGain,energy:state.petEnergy-energyBefore,bossDamage:bossBefore-state.bossHp,day:dayKey(),week:state.bossWeek}}state.tasks.push(task)}persist();render();openModalClose();toast('Demo quests added. They are labeled DEMO and can be cleared in Account & preferences.')}
function clearDemoQuests(){const removed=state.tasks.filter(t=>t.demoSample);if(!removed.length){toast('There are no demo quests to clear.');return}for(const task of removed){const reward=task.demoReward;if(!task.completed||!reward)continue;state.xp=Math.max(0,state.xp-reward.xp);state.gold=Math.max(0,(state.gold||0)-reward.gold);state.petEnergy=Math.max(0,state.petEnergy-reward.energy);state.activity[reward.day]=Math.max(0,(state.activity[reward.day]||0)-1);if(reward.week===state.bossWeek)state.bossHp=Math.min(500,state.bossHp+reward.bossDamage)}state.tasks=state.tasks.filter(t=>!t.demoSample);persist();render();toast('Demo quests cleared.','success',{label:'Undo',run:()=>{state.tasks.push(...removed);persist();render()}})}
function maybeWelcome(){if(new URLSearchParams(location.search).get('action')==='quick-add'){localStorage.setItem('tasksphere.welcome.v1','1');return}if(localStorage.getItem('tasksphere.welcome.v1')||state.tasks.length||state.xp||state.focusMinutes)return;const box=document.createElement('div');box.innerHTML='<div class="welcome-mark">✦</div><div class="section-kicker">WELCOME TO TASKSPHERE</div><h2 id="modalTitle">Make your next step feel lighter.</h2><p>Turn a busy day into a few clear quests. Focus sessions, gentle progress cues, and your companion help you keep momentum.</p><div class="welcome-features"><span>✦ Add and organize quests</span><span>◷ Focus with a timer that survives reloads</span><span>⚡ Earn XP, gold, and streaks</span></div><div class="modal-row"><button class="primary-btn" id="welcomeDemo">Try sample quests</button><button class="secondary-btn" id="welcomeBlank" style="margin:0">Start with a blank board</button></div><p class="setup-note">You can clear sample quests any time in Account & preferences.</p>';openModal(box);$('welcomeDemo').addEventListener('click',()=>{localStorage.setItem('tasksphere.welcome.v1','1');loadDemoQuests()});$('welcomeBlank').addEventListener('click',()=>{localStorage.setItem('tasksphere.welcome.v1','1');openModalClose()})}
function dayOffset(iso){if(!iso)return null;const target=new Date(iso+'T00:00:00'),today=new Date();today.setHours(0,0,0,0);return Math.round((target-today)/86400000)}
function dueDescription(iso){const n=dayOffset(iso);if(n===null)return '';if(n<0)return 'Overdue · '+Math.abs(n)+'d';if(n===0)return 'Due today';if(n===1)return 'Due tomorrow';return 'Due in '+n+'d'}
function showShop(){const content=document.createElement('div');content.innerHTML=`<div class="section-kicker">MAKE IT YOURS</div><h2 id="modalTitle">Theme shop</h2><p>Earn gold from quests and bounties, then spend it to unlock a new workspace look. <strong style="color:var(--accent)">${state.gold||0} gold available</strong></p>`;THEMES.forEach(t=>{const row=document.createElement('div');row.className='theme-option';row.innerHTML=`<div class="theme-swatch"><div class="swatches">${t.colors.map(c=>`<i style="background:${c}"></i>`).join('')}</div><div><strong>${t.name}</strong><div class="theme-requirement">${t.cost===0?'Available now':`${t.cost} gold · Level ${t.level}`}</div></div></div>`;const unlocked=(state.unlockedThemes||['default']).includes(t.id);const canUnlock=levelInfo().rank.level>=t.level&&(state.gold||0)>=t.cost;const btn=document.createElement('button');btn.textContent=state.theme===t.id?'Equipped':unlocked?'Equip':levelInfo().rank.level<t.level?'Locked':`Unlock · ${t.cost}g`;btn.disabled=state.theme===t.id||(!unlocked&&!canUnlock);btn.addEventListener('click',()=>applyTheme(t.id));row.append(btn);content.append(row)});openModal(content)}
function openModal(content){$('modalContent').replaceChildren(content);$('modalBackdrop').hidden=false;setTimeout(()=>$('modalClose').focus(),0)}function openModalClose(){const title=$('modalContent').querySelector('#modalTitle')?.textContent||'';if(title.includes('Make your next step feel lighter'))localStorage.setItem('tasksphere.welcome.v1','1');$('modalBackdrop').hidden=true}
function showSettings(){const frag=document.createElement('div');frag.innerHTML='<div class="section-kicker">YOUR ACCOUNT</div><h2 id="modalTitle">Account & preferences</h2><p id="authStatus">Local mode is active. Configure Supabase to sync securely across devices.</p><div class="modal-field"><label for="authEmail">Email</label><input id="authEmail" type="email" autocomplete="email" placeholder="you@example.com"></div><div class="modal-field"><label for="authPassword">Password</label><input id="authPassword" type="password" autocomplete="current-password" placeholder="At least 6 characters"></div><div class="modal-row"><button class="primary-btn" id="signInBtn">Sign in</button><button class="secondary-btn" id="signUpBtn" style="margin:0">Create account</button></div><button class="text-btn" id="signOutBtn" style="margin-top:13px;display:none">Sign out</button><hr class="modal-divider"><div class="section-kicker">COMFORT & ACCESSIBILITY</div><div class="modal-field"><label for="focusDefaultSelect">Default focus length</label><select id="focusDefaultSelect"><option value="15">15 minutes</option><option value="25">25 minutes</option><option value="45">45 minutes</option><option value="60">60 minutes</option></select></div><div class="modal-field"><label for="soundVolumeInput">Sound volume <span id="soundVolumeValue"></span></label><input id="soundVolumeInput" type="range" min="0" max="100" step="5"></div><div class="modal-field"><label for="motionSelect">Animation intensity</label><select id="motionSelect"><option value="full">Full</option><option value="subtle">Subtle</option><option value="reduced">Reduced</option></select></div><hr class="modal-divider"><div class="section-kicker">PRESENTATION DEMO</div><p>Sample quests are clearly marked and can be cleared without deleting your own quests.</p><div class="modal-row"><button class="secondary-btn" id="loadDemoBtn" style="margin:0">Load demo quests</button><button class="text-btn" id="resetDemoBtn">Clear demo quests</button></div><p class="setup-note">Cloud sync only activates after you add your Supabase project URL and public anon key in <code>script.js</code> and run <code>supabase.sql</code>. Never use a service role key in this page.</p>';openModal(frag);$('authStatus').textContent=user?`Signed in as ${user.email}. Cloud sync is active.`:cloudConfigured()?'Connect your account to sync cloud data.':'Local mode is active. Configure Supabase to sync securely across devices.';$('signOutBtn').style.display=user?'inline-block':'none';$('focusDefaultSelect').value=String(state.focusDefault||25);$('soundVolumeInput').value=Math.round((state.soundVolume??.45)*100);$('soundVolumeValue').textContent=`${$('soundVolumeInput').value}%`;$('motionSelect').value=state.motionLevel||'full';$('signInBtn').addEventListener('click',()=>authAction('signin'));$('signUpBtn').addEventListener('click',()=>authAction('signup'));$('signOutBtn').addEventListener('click',async()=>{await supabaseClient?.auth.signOut();user=null;syncStatus('ready','Saved on this device');openModalClose();toast('Signed out. Your local copy remains available.')});$('focusDefaultSelect').addEventListener('change',e=>{state.focusDefault=Number(e.target.value);if(!timerRunning&&state.focus.mode==='focus'){state.focus={minutes:state.focusDefault,mode:'focus'};focusSeconds=state.focusDefault*60;document.querySelectorAll('.timer-presets button').forEach(x=>x.classList.toggle('selected',Number(x.dataset.minutes)===state.focusDefault));updateTimerUI()}persist()});$('soundVolumeInput').addEventListener('input',e=>{$('soundVolumeValue').textContent=`${e.target.value}%`;state.soundVolume=Number(e.target.value)/100;persist()});$('motionSelect').addEventListener('change',e=>{state.motionLevel=e.target.value;applyMotionPreference();persist()});$('loadDemoBtn').addEventListener('click',loadDemoQuests);$('resetDemoBtn').addEventListener('click',clearDemoQuests)}async function authAction(action){if(!supabaseClient)return toast('Set the Supabase URL and anon key in script.js first.','error');const email=$('authEmail').value.trim(),password=$('authPassword').value;if(!email||password.length<6)return toast('Enter a valid email and password (6+ characters).','error');const result=action==='signin'?await supabaseClient.auth.signInWithPassword({email,password}):await supabaseClient.auth.signUp({email,password});if(result.error)return toast(result.error.message,'error');user=result.data.user;if(result.data.session){await loadCloud();openModalClose();toast(action==='signin'?'Signed in and syncing.':'Account created and syncing.')}else{$('authStatus').textContent='Check your email to confirm your account, then sign in.';toast('Check your email to confirm your account.')}}
async function loadCloud(){if(!user||!supabaseClient)return;syncStatus('pending','Loading cloud backup…');const {data,error}=await supabaseClient.from('tasksphere_profiles').select('payload,updated_at').eq('user_id',user.id).maybeSingle();if(error){syncStatus('error','Cloud sync needs attention');console.error(error);return}if(data?.payload&&data.updated_at&&new Date(data.updated_at)>new Date(Number(localStorage.getItem('tasksphere.lastCloudAt')||0))){state={...blankState(),...data.payload};localStorage.setItem(STORAGE_KEY,JSON.stringify(state));localStorage.setItem('tasksphere.lastCloudAt',String(new Date(data.updated_at).getTime()));render();toast('Latest cloud backup loaded.')}syncStatus('ready',`Synced · ${user.email}`)}
async function syncCloud(){if(!user||!supabaseClient){syncStatus('ready',cloudConfigured()?'Local mode · sign in to sync':'Saved on this device');return}if(!navigator.onLine){syncStatus('pending','Offline · changes queued');return}syncStatus('pending','Syncing securely…');const queue=JSON.parse(localStorage.getItem(QUEUE_KEY)||'[]');const payload=queue.length?queue[queue.length-1].payload:state;const {error}=await supabaseClient.from('tasksphere_profiles').upsert({user_id:user.id,payload,updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error){syncStatus('error','Cloud sync paused · local copy safe');console.error('TaskSphere sync error',error);return}localStorage.removeItem(QUEUE_KEY);localStorage.setItem('tasksphere.lastCloudAt',String(Date.now()));syncStatus('ready',`Synced · ${user.email}`)}
function exportData(){const blob=new Blob([JSON.stringify({app:'TaskSphere',version:1,exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`tasksphere-backup-${dayKey()}.json`;a.click();URL.revokeObjectURL(a.href);toast('Backup downloaded.')}
async function importData(file){try{const parsed=JSON.parse(await file.text()),incoming=parsed.data||parsed;if(!Array.isArray(incoming.tasks)||!Number.isFinite(Number(incoming.xp)))throw Error('This file does not look like a TaskSphere backup.');if(!confirm('Replace this device’s TaskSphere data with the selected backup?'))return;state={...blankState(),...incoming};persist();render();toast('Backup restored.')}catch(e){toast(e.message||'Could not read this backup.','error')}}
async function shareProgress(){const {rank}=levelInfo(),done=state.tasks.filter(t=>t.completed).length;const text=`✦ My TaskSphere progress\n${done} quests completed · ${state.xp} XP · Level ${rank.level} ${rank.name} · ${currentStreak()} day streak\nSmall steps, big momentum.`;const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=630;const ctx=canvas.getContext('2d');const grad=ctx.createLinearGradient(0,0,1200,630);grad.addColorStop(0,'#151321');grad.addColorStop(1,'#282044');ctx.fillStyle=grad;ctx.fillRect(0,0,1200,630);ctx.fillStyle='#a78bfa';ctx.beginPath();ctx.arc(1010,95,195,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.3;ctx.fillStyle='#d59bff';ctx.beginPath();ctx.arc(90,600,160,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#d4c7ff';ctx.font='700 28px Manrope, sans-serif';ctx.fillText('✦ TASKSPHERE',84,100);ctx.fillStyle='#f8f6ff';ctx.font='800 68px Manrope, sans-serif';ctx.fillText('Small steps,',84,225);ctx.fillText('big momentum.',84,305);ctx.fillStyle='#c6bed9';ctx.font='500 26px DM Sans, sans-serif';ctx.fillText(`${done} quests completed     ·     ${currentStreak()} day streak`,86,385);ctx.fillStyle='#fff';ctx.font='700 27px DM Sans, sans-serif';ctx.fillText(`${state.xp.toLocaleString()} XP`,86,470);ctx.fillStyle='#bdaaff';ctx.fillText(`LEVEL ${rank.level}  ·  ${rank.name.toUpperCase()}`,320,470);ctx.fillStyle='#9c96ae';ctx.font='500 20px DM Sans, sans-serif';ctx.fillText('My TaskSphere progress',86,555);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(blob){const file=new File([blob],`tasksphere-progress-${dayKey()}.png`,{type:'image/png'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'My TaskSphere progress',text});return}catch(e){if(e.name==='AbortError')return}}const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=file.name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}try{await navigator.clipboard.writeText(text);toast('Progress card downloaded · summary copied too.')}catch{toast('Progress card downloaded.')}}
function openQuestLog(){const done=state.tasks.filter(t=>t.completed).sort((a,b)=>(b.completedAt||0)-(a.completedAt||0));const frag=document.createElement('div');frag.innerHTML='<div class="section-kicker">LOOK HOW FAR YOU HAVE COME</div><h2 id="modalTitle">Completed quest log</h2><p>Your finished quests, one small win at a time.</p>';if(!done.length){const p=document.createElement('p');p.textContent='No completed quests yet. Your first win is waiting.';frag.append(p)}done.slice(0,60).forEach(t=>{const row=document.createElement('div');row.className='log-row';const name=document.createElement('strong');name.textContent=t.text;const meta=document.createElement('span');meta.textContent=`${CATEGORIES[t.category]||t.category} · +${XP[t.priority]||10} XP`;row.append(name,meta);frag.append(row)});openModal(frag)}
function paletteActions(query=''){const q=query.toLowerCase();const actions=[{label:'Add a new quest',icon:'fa-plus',run:openQuickAdd},{label:'Start or pause focus timer',icon:'fa-play',run:startTimer},{label:'Open theme shop',icon:'fa-palette',run:showShop},{label:'Open account and sync settings',icon:'fa-cloud',run:showSettings},{label:'Export backup',icon:'fa-download',run:exportData},{label:'Show completed quest log',icon:'fa-scroll',run:openQuestLog},{label:'Share progress card',icon:'fa-share-nodes',run:shareProgress},...state.tasks.filter(t=>!t.completed).map(t=>({label:`Focus on: ${t.text}`,icon:'fa-bullseye',run:()=>{$('focusTask').value=t.id;$('focus').scrollIntoView({behavior:'smooth',block:'center'})}}))];return actions.filter(a=>a.label.toLowerCase().includes(q))}
function drawPalette(){const results=paletteActions($('paletteInput').value),wrap=$('paletteResults');wrap.replaceChildren();paletteIndex=0;if(!results.length){wrap.innerHTML='<div class="palette-empty">No matching commands or quests.</div>';return}results.forEach((a,i)=>{const row=document.createElement('div');row.className=`palette-item ${i===0?'selected':''}`;row.innerHTML=`<i class="fa-solid ${a.icon}"></i><span>${escapeHtml(a.label)}</span>`;row.addEventListener('click',()=>{closePalette();a.run()});wrap.append(row)})}
function openPalette(){$('paletteBackdrop').hidden=false;$('paletteInput').value='';drawPalette();$('paletteInput').focus()}function closePalette(){$('paletteBackdrop').hidden=true}
function wire(){ $('taskForm').addEventListener('submit',e=>{e.preventDefault();createTask({text:$('taskInput').value,category:$('categorySelect').value,priority:$('prioritySelect').value,est:$('estTimeInput').value,due:$('dueDateInput').value,repeat:$('repeatSelect').value});e.target.reset();$('prioritySelect').value='medium';$('taskInput').focus()});const boardTabs=[...document.querySelectorAll('.board-tab')];boardTabs.forEach((b,i)=>{b.addEventListener('click',()=>{boardTabs.forEach(x=>{x.classList.remove('active');x.setAttribute('aria-selected','false');x.tabIndex=-1});b.classList.add('active');b.setAttribute('aria-selected','true');b.tabIndex=0;filter=b.dataset.filter;renderTasks()});b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?boardTabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+boardTabs.length)%boardTabs.length;boardTabs[next].focus();boardTabs[next].click()})});$('searchInput').addEventListener('input',renderTasks);$('sortSelect').addEventListener('change',renderTasks);$('openShop').addEventListener('click',showShop);$('settingsBtn').addEventListener('click',showSettings);$('accountAvatar').addEventListener('click',showSettings);$('timerStart').addEventListener('click',startTimer);$('chimeToggle').addEventListener('click',toggleChime);$('immersiveToggle').addEventListener('click',toggleImmersive);$('timerReset').addEventListener('click',()=>{clearInterval(timerInterval);timerRunning=false;timerDeadline=0;saveTimerSession('done');focusSessionId='';state.focus={minutes:state.focusDefault||25,mode:'focus'};focusSeconds=(state.focusDefault||25)*60;document.querySelectorAll('.timer-presets button').forEach(x=>x.classList.toggle('selected',Number(x.dataset.minutes)===(state.focusDefault||25)));updateTimerUI();$('timerStart').innerHTML='<i class="fa-solid fa-play"></i> Start focus';persist()});document.querySelectorAll('.timer-presets button').forEach(b=>b.addEventListener('click',()=>setTimerMinutes(Number(b.dataset.minutes))));$('feedPet').addEventListener('click',feedPet);$('petAvatar').addEventListener('click',interactPet);$('petInteract').addEventListener('click',interactPet);$('claimBounty').addEventListener('click',claimBounty);$('monthToggle').addEventListener('click',()=>setAnalytics('month'));$('yearToggle').addEventListener('click',()=>setAnalytics('year'));$('shareBtn').addEventListener('click',shareProgress);$('exportBtn').addEventListener('click',exportData);$('soundToggle').addEventListener('click',toggleSound);$('quickAddBtn').addEventListener('click',openQuickAdd);$('quickAddFab').addEventListener('click',openQuickAdd);$('importFile').addEventListener('change',e=>{if(e.target.files[0])importData(e.target.files[0]);e.target.value=''});$('questLogBtn').addEventListener('click',openQuestLog);$('modalClose').addEventListener('click',openModalClose);$('modalBackdrop').addEventListener('click',e=>{if(e.target===$('modalBackdrop'))openModalClose()});$('commandBtn').addEventListener('click',openPalette);$('paletteInput').addEventListener('input',drawPalette);$('paletteBackdrop').addEventListener('click',e=>{if(e.target===$('paletteBackdrop'))closePalette()});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openPalette()}if(e.key.toLowerCase()==='n'&&!e.metaKey&&!e.ctrlKey&&!e.altKey&&!/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)&&!e.target.isContentEditable&&!document.body.classList.contains('focus-immersive')){e.preventDefault();openQuickAdd()}if(e.key==='Escape'){if(document.body.classList.contains('focus-immersive'))toggleImmersive();closePalette();openModalClose()}if(e.key==='Enter'&&!$('paletteBackdrop').hidden){const a=paletteActions($('paletteInput').value)[paletteIndex];if(a){closePalette();a.run()}}if(!$('paletteBackdrop').hidden&&e.key==='ArrowDown'){e.preventDefault();const rows=[...document.querySelectorAll('.palette-item')];if(rows.length){paletteIndex=(paletteIndex+1)%rows.length;rows.forEach((r,i)=>r.classList.toggle('selected',i===paletteIndex))}}if(!$('paletteBackdrop').hidden&&e.key==='ArrowUp'){e.preventDefault();const rows=[...document.querySelectorAll('.palette-item')];if(rows.length){paletteIndex=(paletteIndex-1+rows.length)%rows.length;rows.forEach((r,i)=>r.classList.toggle('selected',i===paletteIndex))}}});document.querySelectorAll('.side-nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('.side-nav a').forEach(x=>x.classList.remove('active'));a.classList.add('active')}));document.addEventListener('visibilitychange',()=>{if(!document.hidden&&timerRunning)tickTimer()})}
function setAnalytics(range){analyticsRange=range;$('monthToggle').classList.toggle('active',range==='month');$('yearToggle').classList.toggle('active',range==='year');$('heatmap').classList.toggle('year-view',range==='year');renderHeatmap()}
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY&&event.newValue){try{state={...blankState(),...JSON.parse(event.newValue)};render();updateTimerUI()}catch{}return}if(event.key!==TIMER_SESSION_KEY)return;if(!event.newValue){clearInterval(timerInterval);timerRunning=false;timerDeadline=0;focusSessionId='';focusSeconds=(state.focus.minutes||state.focusDefault||25)*60;$('timerStart').innerHTML='<i class="fa-solid fa-play"></i> Start focus';updateTimerUI();return}try{const saved=JSON.parse(event.newValue);if(saved.id&&saved.id===focusSessionId&&saved.status==='running'&&timerRunning&&timerDeadline===Number(saved.deadline))return;focusSessionId=saved.id||'';state.focus={minutes:saved.minutes||25,mode:saved.mode==='break'?'break':'focus'};clearInterval(timerInterval);if(saved.status==='running'){timerRunning=true;timerDeadline=Number(saved.deadline);focusSeconds=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));lastChimeMinute=Math.ceil(focusSeconds/60);$('timerStart').innerHTML='<i class="fa-solid fa-pause"></i> Pause session';timerInterval=setInterval(tickTimer,250)}else{timerRunning=false;timerDeadline=0;focusSeconds=Math.max(0,Number(saved.remaining)||0);$('timerStart').innerHTML='<i class="fa-solid fa-play"></i> Resume focus'}updateTimerUI()}catch{}});
function registerOfflineApp(){if('serviceWorker'in navigator&&(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1'))navigator.serviceWorker.register('./sw.js').catch(()=>{})}
function init(){applyDailyRules();restoreTimerSession();wire();$('upcomingViewAll').addEventListener('click',()=>$('quests').scrollIntoView({behavior:'smooth',block:'start'}));render();updateTimerUI();maybeWelcome();if(new URLSearchParams(location.search).get('action')==='quick-add')openQuickAdd();if(timerRunning){$('timerStart').innerHTML='<i class="fa-solid fa-pause"></i> Pause session';timerInterval=setInterval(tickTimer,250);tickTimer()}else if(expiredTimerSession){completeFocus()}registerOfflineApp();initCloud();window.addEventListener('online',()=>syncCloud());window.addEventListener('beforeunload',()=>{if(user)navigator.sendBeacon?.(`${SUPABASE_URL}/rest/v1/tasksphere_profiles`,'')});}
init();
